import{_ as a,o as t,c as s,ai as i}from"./chunks/framework.DQi1ytmF.js";const u=JSON.parse('{"title":"Alchemy provider","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/alchemy.md","filePath":"guide/deployment/alchemy.md"}'),o={name:"guide/deployment/alchemy.md"};function n(d,e,r,l,c,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/guide/deployment/alchemy.md for this page in Markdown format</div><h1 id="alchemy-provider" tabindex="-1">Alchemy provider <a class="header-anchor" href="#alchemy-provider" aria-label="Permalink to &quot;Alchemy provider&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Experimental — validate in a non-production account first</p><p>This provider is the least validated part of the deployment tooling. The presets, the plan, the credential checks and the refusal paths are covered by tests through a runtime port, so what CraftTS <em>decides</em> is verified.</p><p>What is <strong>not</strong> verified is the last hop: the adapter that invokes Alchemy&#39;s current CLI has never run against a real Cloudflare or AWS account from this repository. Treat your first deployment as the validation of that adapter — run <code>deploy preview</code> first and read the plan.</p></div><p><code>@craft-ts/deploy-alchemy</code> deploys a CraftTS manifest to Cloudflare or AWS through <a href="https://alchemy.run" target="_blank" rel="noreferrer">Alchemy</a>. It is an optional package: Alchemy never appears in the dependencies of a CraftTS application, and a project that publishes a static artefact somewhere else never installs it.</p><p>Alchemy is a <strong>provider of infrastructure</strong>, not a runtime. It can create the resources, the bindings, the permissions and the state, where a publication provider only uploads an artefact. Both read the same manifest.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --save-dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @craft-ts/deploy-alchemy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alchemy</span></span></code></pre></div><p>The CLI resolves <code>@craft-ts/deploy-&lt;name&gt;</code> from the project being deployed, so nothing else has to be configured. A provider living elsewhere is pointed at with <code>--provider-module</code>.</p><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><p>Credentials are read from the environment. The tooling checks that they are set, never reads their value beyond that, and never writes one to disk.</p><table tabindex="0"><thead><tr><th>Platform</th><th>Variables</th></tr></thead><tbody><tr><td><code>cloudflare</code></td><td><code>CLOUDFLARE_API_TOKEN</code> (or <code>CLOUDFLARE_API_KEY</code>), <code>CLOUDFLARE_ACCOUNT_ID</code> (or <code>ALCHEMY_PROFILE</code>)</td></tr><tr><td><code>aws</code></td><td><code>AWS_ACCESS_KEY_ID</code> (or <code>AWS_PROFILE</code>, <code>AWS_ROLE_ARN</code>), <code>AWS_REGION</code> (or <code>AWS_DEFAULT_REGION</code>)</td></tr></tbody></table><p>Alchemy 2 uses its provider state store and profile configuration. The adapter does not require the legacy <code>ALCHEMY_PASSWORD</code> variable.</p><h2 id="state-and-stages" tabindex="-1">State and stages <a class="header-anchor" href="#state-and-stages" aria-label="Permalink to &quot;State and stages&quot;">​</a></h2><p>Alchemy reconciles against a recorded state, which is what lets a preview tell a creation from an update. Every resource name carries the application <strong>and</strong> the stage:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>demo-production-worker</span></span>
<span class="line"><span>demo-preview-42-worker</span></span></code></pre></div><p>A stage is passed with <code>--stage</code>; it defaults to the <code>environment</code> of the manifest. Two stages never share a resource, so a preview deployment cannot overwrite production.</p><h2 id="preview-before-mutating" tabindex="-1">Preview before mutating <a class="header-anchor" href="#preview-before-mutating" aria-label="Permalink to &quot;Preview before mutating&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft-ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alchemy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> staging</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plan: alchemy → stage staging (2 resource(s))</span></span>
<span class="line"><span>  create    cloudflare:KV.Namespace demo-staging-sessions</span></span>
<span class="line"><span>    binding: SESSIONS</span></span>
<span class="line"><span>  update    cloudflare:Worker demo-staging-worker</span></span>
<span class="line"><span>    entrypoint: dist/apps/demo/worker.js</span></span>
<span class="line"><span>    assets: dist/apps/demo</span></span>
<span class="line"><span>  note: Alchemy 2.0.0-beta.76, stage \`staging\`.</span></span>
<span class="line"><span>Preview only: nothing was created, updated or deleted.</span></span></code></pre></div><p>The preview opens Alchemy in its read phase, so it resolves the recorded state and creates nothing. A resource Alchemy still records that the manifest no longer declares appears as <code>delete</code>: hiding it would understate the change.</p><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft-ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alchemy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> staging</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span></span></code></pre></div><p><code>deploy</code> runs, in order: the manifest check, the provider check (credentials, artefacts, presets), then the same preview. It refuses to apply until <code>--yes</code> approves the plan, and reports <code>CRAFT_DEPLOY_DEPLOY_NOT_CONFIRMED</code> otherwise.</p><p>Outputs are printed as <code>&lt;resource&gt;.&lt;key&gt;</code>, and the first <code>url</code> output becomes the deployment URL:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>url: https://demo-staging.workers.dev</span></span>
<span class="line"><span>output demo-staging-sessions.id: 5f1c…</span></span>
<span class="line"><span>output demo-staging-worker.url: https://demo-staging.workers.dev</span></span>
<span class="line"><span>Deployed to stage \`staging\` with alchemy.</span></span></code></pre></div><p>Use <code>--json</code> to get <code>{ applied, plan, result, diagnostics }</code> for a CI step.</p><h2 id="what-each-manifest-becomes" tabindex="-1">What each manifest becomes <a class="header-anchor" href="#what-each-manifest-becomes" aria-label="Permalink to &quot;What each manifest becomes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Manifest</th><th>Resources</th></tr></thead><tbody><tr><td><code>static</code> on <code>cloudflare</code></td><td><code>Website.StaticSite</code></td></tr><tr><td><code>worker</code> on <code>cloudflare</code></td><td>binding resources, then <code>Worker</code></td></tr><tr><td><code>static</code> on <code>aws</code></td><td><code>Website.StaticSite</code></td></tr><tr><td><code>lambda</code> on <code>aws</code></td><td><code>Lambda.Function</code> with its built-in Function URL</td></tr><tr><td><code>node</code> on <code>aws</code></td><td>refused; use the Docker provider or an image preset</td></tr></tbody></table><p>Bindings map to the resource their <code>type</code> names — <code>kv</code>, <code>r2</code>, <code>d1</code>, <code>queue</code>, <code>durable_object</code>. A binding typed <code>secret</code> is never created: its value must already exist in the Alchemy state or the environment, and the plan says so instead of carrying it. Any other type is refused with <code>CRAFT_DEPLOY_PROVIDER_UNSUPPORTED_RESOURCE</code> rather than silently dropped.</p><p>The Function URL keeps the <code>{ id, input, context }</code> protocol of a server-function, so the same function behaves as it does locally.</p><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Alchemy has no &quot;undo&quot;: a rollback is a deployment of the previous artefact.</p><ol><li>Check out the commit whose artefact was healthy, or restore its <code>dist/&lt;app&gt;/craft-deployment-manifest.json</code>.</li><li>Rebuild it: the manifest is byte-identical for a given input, so a rebuild of the same commit produces the same declaration.</li><li><code>npx craft-ts deploy preview --provider alchemy --stage &lt;stage&gt;</code> and read the plan: a rollback shows <code>update</code> on the resources that moved forward.</li><li>Apply it with <code>--yes</code>.</li></ol><p>Two things do not roll back on their own and have to be handled explicitly: a resource deleted by a finalize is recreated empty, and a stateful binding such as a KV namespace or a bucket keeps the data written by the newer version. Roll a stateful change back through the data, not through the deployment.</p><h2 id="what-stays-in-craftts-what-is-delegated" tabindex="-1">What stays in CraftTS, what is delegated <a class="header-anchor" href="#what-stays-in-craftts-what-is-delegated" aria-label="Permalink to &quot;What stays in CraftTS, what is delegated&quot;">​</a></h2><p>CraftTS owns the manifest, the checks, the resolved artefact and the plan shape. It decides <em>what</em> has to exist, and it refuses to deploy a manifest that does not pass <code>craft-ts check</code>.</p><p>Alchemy owns the resources, the state, the credentials handling and the reconciliation. It decides <em>how</em> what CraftTS declared comes to exist.</p><p>The adapter generates a temporary Alchemy 2 stack and invokes the installed Alchemy CLI. <code>ALCHEMY_RESOURCE_EXPORTS</code> maps each planned resource type to the current module and nested export used in that generated stack.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>The adapter over the Alchemy API has never run against a live account, as stated at the top of this page.</li><li>The Fargate fallback runs the artefact as a container: the image build stays outside CraftTS.</li><li>Alchemy has no preset here for the platforms a publication provider already covers (<code>vercel</code>, <code>netlify</code>, <code>firebase</code>, <code>github-pages</code>).</li></ul>`,40)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
